from pathlib import Path
import json,hashlib,re,csv,subprocess
R=Path.cwd();D=R/'docs/development/2026-11-16-zombie-variants';O=D/'evidence'
rows=json.loads((O/'ready-artwork-inspection.json').read_text());ready=json.loads((O/'ready-input-identity.json').read_text());check=json.loads((O/'artwork-readiness.json').read_text())
lines=['# Authored artwork inspection — refreshed 2026-11-16','','**READY FOR IMPLEMENTATION.** The owner supplied both scientist attack frames and the corpse frame and explicitly resumed handoff preparation. All three are verified 32×32 with binary alpha. The old color error is corrected in the source. This replaces the earlier missing-art/pending-color status; it is input verification, not in-game acceptance.','','No images were edited by the agent. All **122** current assets, including the new editor copies, are hashed in [ready-input-identity.json](evidence/ready-input-identity.json). [Current image details](evidence/ready-artwork-inspection.json) cover **81 PNGs** in the zombie/weapon trees. The table below lists the **52 direct inputs: 45 zombie files and seven weapon files**. Editor copies remain protected but are not automatic runtime inputs.','','Alpha is binary (0/255) for every direct input. Dimensions are decoded. Changed means current RGBA pixels differ from tracked HEAD; hashes identify the exact current source files. Original initial-identity.json, artwork-inspection.json, architecture-evidence.json, generator rejection logs and planning-completion.json remain dated pre-correction evidence. Never use their older art identities to overwrite current PNGs.','','| File | Actual size | Git / pixel comparison | SHA-256 |','| --- | --- | --- | --- |']
for r in rows:
 if not r['direct_input']:continue
 status='new, untracked' if r['git']=='untracked' else 'pixels changed' if r['changed_pixels_vs_head'] else 'unchanged'
 lines.append(f"| `{Path(r['path']).name}` | {r['width']}×{r['height']} | {status} | `{r['sha256']}` |")
lines+=['','## Completed inputs and generator work','','All selected scientist poses are now present: seven used 8×8 base sources, six 16×16 sources and eight 32×32 poses. The new attacks each contain 483 opaque pixels; the corpse contains 370. Both species have authored near standing frames to integrate. Preserve unused frames too; no substitutes are needed.','','The two held shotgun images are still 20×16; pickup/pause sources remain unchanged 16×16. Current content replaces historical generated expectations. Recheck generated output during implementation rather than claiming these PNG checks prove a playable ROM.','','The earlier bad color at scientist walking_02_32×32 (5,29) and shotgun_held_shoot (4,2)/(5,2), zero-based, is verified as opaque #000000. No #03000F occurs in any of the 52 direct inputs. **Do not introduce the earlier proposed alias.**','','Required explicit generator mappings: scientist base white #FFFFFF → existing index 12; near gray #797878 → existing index 3; new attack dark gray #4D4D4D → existing index 2. Each attack contains 14 pixels of the last color. The weapon branch already uses these gray mappings; extend the zombie branch without changing hardware palette values or PNGs. This is scoped implementation work, not an unresolved owner-art decision.','','[Artwork readiness](evidence/artwork-readiness.json) includes exact new-frame hashes, colors, corrected coordinates and the change set since the original inspection. Four original direct files changed during owner editing (both held-shotgun files and both scientist 32×32 walk frames); the current versions are authoritative. Three direct frames and five protected editor copies were added.']
(D/'ARTWORK_INSPECTION.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert all(sha(R/p)==h for p,h in ready['files'].items())
assert subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()==ready['head']
q=[x for x in csv.DictReader((R/'docs/maintenance/2026-10-23/evidence/protected-artwork.csv').open(encoding='utf-8')) if x['path'].startswith('.artifact-quarantine/')]
assert len(q)==18 and all(sha(R/x['path'])==x['sha256'] for x in q)
broken=[]
for p in [R/'AGENTS.md',R/'docs/README.md',*D.glob('*.md')]:
 for target in re.findall(r'\]\(([^)]+)\)',p.read_text(encoding='utf-8')):
  if '://' not in target and not target.startswith('#') and not (p.parent/target.split('#')[0]).exists():broken.append([p.name,target])
assert not broken,broken
prompt=(D/'SOL_EXECUTION_PROMPT.md').read_text();assert 'Action: START' in prompt and 'Action: HOLD' not in prompt
assignment=(D/'ENGINEERING_ASSIGNMENT.md').read_text();assert 'READY FOR SOL IMPLEMENTATION' in assignment
subprocess.run(['git','diff','--check'],check=True)
result=dict(date='2026-11-16',scope='Refresh existing untransferred Sol assignment after owner-supplied artwork and explicit resumption',status='READY_FOR_MANUAL_SOL_HANDOFF',owner_dependencies_resolved=['Three scientist near frames supplied and inspected','Three accidental color pixels corrected to opaque #000000'],remaining_owner_art_blockers=[],generator_mapping_additions=['WorldSprite #FFFFFF -> 12','NearZombie #797878 -> 3','NearZombie #4D4D4D -> 2'],protected_current_assets_verified=122,protected_quarantine_art_verified=18,production_source_files_unchanged=63,head_unchanged=ready['head'],source_tools_build_config_unchanged=True,agent_image_edits=0,broken_links=broken,no_runtime_build_or_campaign=True,no_commit_or_push=True,no_dispatch=True,initial_transfer_to_sol='Not yet performed by owner',historical_evidence='Original snapshots/logs retained unchanged; ready-* records are the current handoff inputs')
(O/'ready-handoff-completion.json').write_text(json.dumps(result,indent=2)+'\n')
manifest={p.relative_to(R).as_posix():sha(p) for p in [R/'AGENTS.md',R/'docs/WORK_RULES.md',R/'docs/README.md',*D.rglob('*')] if p.is_file() and p.name!='ready-handoff-manifest.json'}
(O/'ready-handoff-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps(result,indent=2))
